#include <bits/stdc++.h>

using namespace std;

int main() {
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        int m = 3 * n;
        vector < long long > ap(m);
        int aa;
        for(auto &x:ap) cin>>x;
        sort(ap.begin(), ap.end(), greater < long long > ());
        vector < long long > p(m + 1, 0);
        for (int i = 0; i < m; i++) {
            p[i + 1] = p[i] + ap[i];
        }
        auto f = [ & ](long long a, long long b) -> long long {
            long long c = n - a - b;
            long long s2 = a + 2 * b;
            long long s3 = s2 + 3 * c;
            return 6 * p[a] + 4 * (p[s2] - p[a]) + 3 * (p[s3] - p[s2]);
        };
        long long best = 0;
        for (int a = 0; a <= n; a++) {
            int lo = 0;
            int hi = n - a;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if (f(a, mid + 1) > f(a, mid)) lo = mid + 1;
                else hi = mid;
            }
            best = max(best, f(a, lo));
        }
        cout << best << endl;
    }
}
